={{ JSON.stringify({ query: `query Collections($after: String, $ns: String!, $key: String!) {
  collections(first: 100, after: $after, query: "published_status:published") {
    pageInfo { hasNextPage endCursor }
    nodes { id handle title sortOrder keyword: metafield(namespace: $ns, key: $key) { value } }
  }
}`, variables: { after: null, ns: $('Setup settings').first().json.keyword_namespace, key: $('Setup settings').first().json.keyword_key } }) }}

parameters.jsCode:
const s = $('Setup settings').first().json;
const have = new Set($('Existing rows').all().map(i => i.json.handle).filter(Boolean));
return $('Read collections').all().flatMap(i => i.json.data.collections.nodes)
  .filter(c => !have.has(c.handle))
  .map(c => ({ json: {
    handle: c.handle,
    gid: c.id,
    title: c.title,
    keyword: String((c.keyword && c.keyword.value) || c.title).toLowerCase().trim(),
    other_searches: '',
    // Best selling and Newest keep Shopify's sort; a hand-set Manual order keeps your order
    mode: s.leave_alone.includes(c.sortOrder) ? 'skip' : c.sortOrder === 'MANUAL' ? 'tier' : 'keyword'
  } }));

const s = $('Sort settings').first().json;
const items = $('Read collection products').all();
if (s.match_mode !== 'blend') return items.map(i => ({ json: i.json }));
const rows = $('Collections to sort').all().map(i => i.json);
const searches = r => [r.keyword, ...String(r.other_searches || '').split(',')].map(x => x.trim()).filter(Boolean);
// Vectors saved on earlier runs, so only new or renamed titles are embedded again
const saved = new Map($('Saved vectors').all().filter(i => i.json.text).map(i => [i.json.text, JSON.parse(i.json.vector)]));
const texts = new Set();
items.forEach((it, i) => {
  const r = rows[i], col = it.json.data && it.json.data.collection;
  if (!col || r.mode !== 'keyword') return;
  searches(r).forEach(k => texts.add(s.query_prefix + k));
  col.products.nodes.forEach(p => texts.add(s.doc_prefix + p.title));
});
const missing = [...texts].filter(t => !saved.has(t)), fresh = [];
for (let i = 0; i < missing.length; i += 64) {
  const batch = missing.slice(i, i + 64);
  const res = await this.helpers.httpRequest({ method: 'POST', url: s.embed_url, json: true, timeout: 60000,
    headers: s.embed_api_key ? { Authorization: 'Bearer ' + s.embed_api_key } : {},
    body: { model: s.embed_model, input: batch } });
  // Ollama returns embeddings; OpenAI-style APIs return data[].embedding
  const vecs = res.embeddings || (res.data || []).map(d => d.embedding);
  batch.forEach((t, j) => { saved.set(t, vecs[j]); fresh.push({ text: t, vector: JSON.stringify(vecs[j].map(x => Math.round(x * 1e4) / 1e4)) }); });
}
const cos = (a, b) => { let d = 0, x = 0, y = 0; for (let i = 0; i < a.length; i++) { d += a[i] * b[i]; x += a[i] * a[i]; y += b[i] * b[i]; } return d / Math.sqrt(x * y); };
return items.map((it, i) => {
  const r = rows[i], col = it.json.data && it.json.data.collection;
  const out = { ...it.json, new_vectors: i === 0 ? fresh : [] };
  if (!col || r.mode !== 'keyword') return { json: out };
  out.meaning = {};
  for (const k of searches(r)) {
    const raw = col.products.nodes.map(p => [p.id, cos(saved.get(s.query_prefix + k), saved.get(s.doc_prefix + p.title))]);
    // Rescaled 0 to 1 within the collection, so meaning sits on the same scale as the word score
    const lo = Math.min(...raw.map(x => x[1])), hi = Math.max(...raw.map(x => x[1]));
    out.meaning[k] = Object.fromEntries(raw.map(([id, c]) => [id, hi > lo ? (c - lo) / (hi - lo) : 1]));
  }
  return { json: out };
});

const s = $('Sort settings').first().json;
const rows = $('Collections to sort').all().map(i => i.json);
const tokens = t => [...new Set(String(t).toLowerCase().replace(/wi-?fi/g, 'wifi').split(/[^a-z0-9]+/)
  .filter(w => w && !s.stopwords.includes(w))
  .map(w => w.length > 4 && w.endsWith('ies') ? w.slice(0, -3) + 'y' : (w.length > 3 && /[^siu]s$/.test(w) ? w.slice(0, -1) : w))
  .map(w => s.synonyms[w] || w))];
const words = (kw, title) => { const k = tokens(kw), t = tokens(title); return k.length ? k.filter(w => t.includes(w)).length / k.length : 0; };
// 0 = can be bought, 1 = sold out, 2 = draft, no image or no price
const tier = p => {
  if (p.status !== 'ACTIVE' || !p.featuredMedia || !(Number(p.priceRangeV2.minVariantPrice.amount) > 0)) return 2;
  if (p.tracksInventory && p.totalInventory <= 0) return 1;
  return 0;
};

return $input.all().map((it, i) => {
  const r = rows[i], col = it.json.data && it.json.data.collection;
  if (!col) return { json: { handle: r.handle, error: 'collection not found', switch: false, moves: [], page1: [], sold_out: [], hidden: 0 } };
  const now = col.products.nodes, ids = now.map(p => p.id);
  // words only, or a blend with the meaning score when match_mode is blend
  const meaning = it.json.meaning;
  const score = (kw, p) => meaning && meaning[kw]
    ? s.meaning_weight * (meaning[kw][p.id] || 0) + (1 - s.meaning_weight) * words(kw, p.title)
    : words(kw, p.title);
  // keyword mode: best match first; tier mode: keep the order you set by hand
  const rank = list => r.mode === 'keyword'
    ? list.map(p => ({ p, sc: score(r.keyword, p), at: ids.indexOf(p.id) })).sort((a, b) => b.sc - a.sc || a.at - b.at).map(x => x.p)
    : list;
  const ready = now.filter(p => tier(p) === 0), placed = [];
  if (r.mode === 'keyword') {
    const main = tokens(r.keyword);
    for (const kw of String(r.other_searches || '').split(',').map(x => x.trim()).filter(Boolean)) {   // one best product per other search, in your order
      const extra = tokens(kw).filter(w => !main.includes(w));   // the words this search adds to the main keyword
      // with words only, the product must contain one of those words; with meaning, the blend decides
      const best = ready.filter(p => !placed.includes(p) && (meaning || extra.some(w => tokens(p.title).includes(w))))
        .map(p => ({ p, sc: score(kw, p) })).sort((a, b) => b.sc - a.sc)[0];
      if (best && best.sc >= s.min_secondary) placed.push(best.p);
    }
  }
  const soldOut = now.filter(p => tier(p) === 1), hidden = now.filter(p => tier(p) === 2);
  const order = [...placed, ...rank(ready.filter(p => !placed.includes(p))), ...rank(soldOut), ...rank(hidden)];
  const report = { handle: r.handle, mode: r.mode, was: col.sortOrder, page1: order.slice(0, 8).map(p => p.title),
    sold_out: soldOut.map(p => p.title), hidden: hidden.length };

  // Shopify re-sorts a collection after it switches to Manual, so a switch gets this run and the moves wait for the next.
  if (col.sortOrder !== 'MANUAL') return { json: { gid: r.gid, ...report, switch: true, moves: [], more: false } };
  const arr = ids.slice(), moves = [];
  order.forEach((p, pos) => {                // only the moves that change the live order
    if (arr[pos] === p.id) return;
    const at = arr.indexOf(p.id);
    if (at >= 0) arr.splice(at, 1);
    arr.splice(pos, 0, p.id);
    moves.push({ id: p.id, newPosition: String(pos) });
  });
  // Shopify takes up to 250 moves a call; anything over max_moves waits for the next run
  return { json: { gid: r.gid, ...report, switch: false, moves: moves.slice(0, s.max_moves), more: moves.length > s.max_moves } };
});

parameters.jsonBody:
={{ JSON.stringify($json.switch
  ? { query: 'mutation($id: ID!) { collectionUpdate(collection: { id: $id, sortOrder: MANUAL }) { userErrors { message } } }', variables: { id: $json.gid } }
  : { query: 'mutation($id: ID!, $moves: [MoveInput!]!) { collectionReorderProducts(id: $id, moves: $moves) { job { id } userErrors { field message } } }',
      variables: { id: $json.gid, moves: $json.moves } }) }}

={{ JSON.stringify((() => {
  const s = $('Sort settings').first().json, all = $('Order products').all().map(i => i.json);
  const moved = all.filter(r => r.switch || r.moves.length || r.error);
  const errs = $('Reorder products').isExecuted ? $('Reorder products').all().flatMap(x => [...(x.json.errors || []),
    ...(x.json.data?.collectionUpdate?.userErrors || []), ...(x.json.data?.collectionReorderProducts?.userErrors || [])]).map(e => e.message) : [];
  // Short lines, so a long run still fits in one Slack message.
  const lines = moved.slice(0, 25).map(r => '*' + r.handle + '*: ' + (r.error || (r.switch ? 'switches to Manual, products move on the next run' : r.moves.length + (r.moves.length === 1 ? ' move' : ' moves') + (r.more ? ' (the rest on the next run)' : ''))) +
    (r.page1.length ? '. First: ' + r.page1.slice(0, 3).map(t => t.slice(0, 40)).join(' / ') : '') +
    (r.sold_out.length ? '. Sold out, last: ' + r.sold_out.length : '') + (r.hidden ? '. Draft, no image or no price: ' + r.hidden : ''));
  return { channel: s.slack_channel, unfurl_links: false, text: (s.dry_run ? ':test_tube: Sort dry run, nothing changed.' : ':arrows_counterclockwise: Sort run.') + '\n' +
    lines.join('\n') + (moved.length > 25 ? '\n...and ' + (moved.length - 25) + ' more' : '') +
    '\nAlready in order: ' + (all.length - moved.length) + '.' + (errs.length ? '\n:x: Shopify errors: ' + errs.join('; ') : '') };
})()) }}
